css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .6); position: relative; }
.loader .bag { position: absolute; left: 3%; top: 20%; width: 55%; height: 54%; border-radius: 10px 20px 20px 10px; background: repeating-linear-gradient(90deg, var(--accent) 0 9%, var(--accent-2) 0 18%); transform-origin: 100% 50%; animation: bellow-squeeze calc(var(--loader-speed) * 1.6) ease-in-out infinite; }
.loader .nozzle { position: absolute; left: 58%; top: 41%; width: 13%; height: 12%; border-radius: 2px 5px 5px 2px; background: linear-gradient(#cbd5e1, #64748b); }
.loader i { position: absolute; top: 42%; left: 71%; width: 8%; height: 8%; border-radius: 50%; background: var(--accent-2); opacity: 0; animation: bellow-puff calc(var(--loader-speed) * 1.6) ease-out infinite; }
.loader i:nth-of-type(2) { top: 28%; animation-delay: calc(var(--loader-speed) * .12); }
.loader i:nth-of-type(3) { top: 56%; animation-delay: calc(var(--loader-speed) * .24); }
@keyframes bellow-squeeze { 0%, 100% { transform: scaleX(1); } 46% { transform: scaleX(.6); } }
@keyframes bellow-puff { 0% { opacity: 0; transform: translateX(0) scale(.5); } 25% { opacity: .95; } 100% { opacity: 0; transform: translateX(200%) scale(1.5); } }
